import type { Tools } from "../generated/tools";

type Grade = "large" | "documented" | "plain";

interface ModuleRecord {
  path: string;
  grade: Grade;
}

function parsePaths(content: string): string[] {
  return content
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line.length > 0);
}

function countNonEmptyLines(text: string): number {
  return text.split("\n").filter((line) => line.trim().length > 0).length;
}

function capModules(paths: string[], max: number): string[] {
  return paths.slice(0, max);
}

function parseSizeBytes(info: string): number {
  const labelled = info.match(/size["']?\s*[:=]\s*(\d+)/i);
  if (labelled !== null) {
    return Number(labelled[1]);
  }
  const bytes = info.match(/(\d+)\s*bytes?\b/i);
  if (bytes !== null) {
    return Number(bytes[1]);
  }
  const first = info.match(/\d+/);
  return first === null ? 0 : Number(first[0]);
}

function gradeModule(sizeBytes: number, text: string): Grade {
  if (sizeBytes > 200) {
    return "large";
  }
  if (text.includes("/**")) {
    return "documented";
  }
  return "plain";
}

function recordModule(records: ModuleRecord[], path: string, grade: Grade): void {
  records.push({ path, grade });
}

function recordFailure(failures: string[], path: string, error: unknown): void {
  failures.push(`${path}: ${String(error)}`);
}

function renderAudit(
  records: ModuleRecord[],
  failures: string[],
  thoughtCount: number
): string {
  const moduleLines = records.map((record) => `- ${record.path}: ${record.grade}`);
  const failureLines = failures.map((failure) => `- ${failure}`);
  return [
    "# Repository Audit",
    "",
    "## modules",
    "",
    ...(moduleLines.length > 0 ? moduleLines : ["- (no modules graded)"]),
    "",
    "## unreadable",
    "",
    ...(failureLines.length > 0 ? failureLines : ["- (none)"]),
    "",
    "## reasoning",
    "",
    `Sequential reasoning ran for this audit: ${thoughtCount} thoughts recorded, numbered 1 through ${thoughtCount} of 3. After the third thought, the reasoning tool was told no further thought was needed.`,
    ""
  ].join("\n");
}

export default async function flow(
  input: { root: string; maxModules: number },
  tools: Tools
) {
  // Step 1: gather the three inventory views at the same time.
  const [listing, tree, allowedDirs] = await Promise.all([
    tools.fs.listDirectoryWithSizes({ path: input.root }),
    tools.fs.directoryTree({ path: input.root }),
    tools.fs.listAllowedDirectories({})
  ]);

  // Step 2: find the TypeScript modules and cap the workload.
  const search = await tools.fs.searchFiles({ path: input.root, pattern: "*.ts" });
  const allMatches = parsePaths(search.content);
  const modulePaths = capModules(allMatches, input.maxModules);

  const topLevelEntries = countNonEmptyLines(listing.content);
  const allowedRoots = parsePaths(allowedDirs.content);

  const moduleRecords: ModuleRecord[] = [];
  const failures: string[] = [];
  const gradeCounts: Record<Grade, number> = { large: 0, documented: 0, plain: 0 };

  // Step 3: fetch metadata, then read, then grade each module.
  for (const modulePath of modulePaths) {
    try {
      const info = await tools.fs.getFileInfo({ path: modulePath });
      const sizeBytes = parseSizeBytes(info.content);
      const source = await tools.fs.readTextFile({ path: modulePath });
      const grade = gradeModule(sizeBytes, source.content);
      recordModule(moduleRecords, modulePath, grade);
      gradeCounts[grade] += 1;
    } catch (error) {
      recordFailure(failures, modulePath, error);
    }
  }

  // Step 4: think the audit through in exactly three sequential thoughts.
  const thought1 = await tools.reasoning.sequentialThinking({
    thought: `Audit thought 1 of 3 — inventory: ${topLevelEntries} top-level entries under ${input.root}, ${allowedRoots.length} allowed root(s) reported by the server, recursive tree captured. Searched for *.ts and capped at ${input.maxModules} module(s): ${moduleRecords.length} graded, ${failures.length} unreadable.`,
    nextThoughtNeeded: true,
    thoughtNumber: 1,
    totalThoughts: 3
  });

  const thought2 = await tools.reasoning.sequentialThinking({
    thought: `Audit thought 2 of 3 — grading: ${gradeCounts.large} large (over 200 bytes), ${gradeCounts.documented} documented (text contains /**), ${gradeCounts.plain} plain. Modules graded plain or large without a JSDoc header are the documentation gaps for the release checklist.`,
    nextThoughtNeeded: true,
    thoughtNumber: 2,
    totalThoughts: 3
  });

  const thought3 = await tools.reasoning.sequentialThinking({
    thought: `Audit thought 3 of 3 — conclusion: ${moduleRecords.length} module(s) audited with ${failures.length} read failure(s) recorded and skipped. Next: write audit.md with the per-module grades and this reasoning trail, then report the counts per grade.`,
    nextThoughtNeeded: false,
    thoughtNumber: 3,
    totalThoughts: 3
  });

  const thoughts = [thought1, thought2, thought3];

  // Step 5: write the audit report next to the sources.
  const report = renderAudit(moduleRecords, failures, thoughts.length);
  await tools.fs.writeFile({
    path: `${input.root}/audit.md`,
    content: report
  });

  // Step 6: report the outcome.
  return {
    large: gradeCounts.large,
    documented: gradeCounts.documented,
    plain: gradeCounts.plain,
    thoughtsRecorded: thoughts.length
  };
}

import type { Tools } from "../generated/tools";

type ModuleGrade = "large" | "documented" | "plain";

interface GradedModule {
  path: string;
  grade: ModuleGrade;
}

/** Turns the raw searchFiles output into absolute module paths. */
function parseModulePaths(content: string): string[] {
  const trimmed = content.trim();
  if (trimmed.startsWith("[")) {
    try {
      const parsed: unknown = JSON.parse(trimmed);
      if (Array.isArray(parsed)) {
        return parsed.filter(
          (entry): entry is string => typeof entry === "string" && entry.endsWith(".ts")
        );
      }
    } catch {
      // Not JSON — fall through to line parsing below.
    }
  }
  return trimmed
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line.length > 0)
    .filter((line) => !/^\d+\s+matches?:/i.test(line))
    .map((line) => line.replace(/^\[(FILE|DIR)\]\s*/i, ""))
    .filter((line) => line.endsWith(".ts"));
}

/** Pulls the byte size out of getFileInfo's textual report. */
function parseSizeBytes(info: string): number {
  const bytesMatch = info.match(/([\d,]+)\s*bytes/i);
  if (bytesMatch !== null) {
    return Number(bytesMatch[1].replace(/,/g, ""));
  }
  const anyNumber = info.match(/\d+/);
  return anyNumber === null ? 0 : Number(anyNumber[0]);
}

/** Grades one module: large over 200 bytes, else documented when it carries JSDoc, else plain. */
function gradeModule(sizeBytes: number, text: string): ModuleGrade {
  if (sizeBytes > 200) {
    return "large";
  }
  if (text.includes("/**")) {
    return "documented";
  }
  return "plain";
}

function recordGrade(grades: GradedModule[], path: string, grade: ModuleGrade) {
  grades.push({ path, grade });
}

function recordFailure(failures: string[], path: string, error: unknown) {
  failures.push(`${path}: ${String(error)}`);
}

function countByGrade(grades: GradedModule[]): Record<ModuleGrade, number> {
  const counts: Record<ModuleGrade, number> = { large: 0, documented: 0, plain: 0 };
  for (const entry of grades) {
    counts[entry.grade] += 1;
  }
  return counts;
}

function excerpt(text: string, maxLines: number): string {
  return text.split("\n").slice(0, maxLines).join("\n");
}

function buildAuditReport(
  root: string,
  grades: GradedModule[],
  failures: string[],
  sizedListing: string,
  tree: string,
  allowedDirectories: string
): string {
  const lines: string[] = ["# Repository audit", "", `Root: ${root}`, ""];
  lines.push(
    "## scope",
    "",
    "Allowed directories:",
    "```",
    excerpt(allowedDirectories, 5),
    "```",
    "",
    "Top of the directory tree:",
    "```",
    excerpt(tree, 12),
    "```",
    ""
  );
  lines.push("## modules", "");
  for (const entry of grades) {
    lines.push(`- ${entry.path}: ${entry.grade}`);
  }
  if (failures.length > 0) {
    lines.push("", "## unreadable modules", "");
    for (const failure of failures) {
      lines.push(`- ${failure}`);
    }
  }
  lines.push(
    "",
    "## reasoning",
    "",
    "Three sequential thoughts were taken (1 of 3, 2 of 3, 3 of 3); after the third no further thought was needed."
  );
  return lines.join("\n");
}

export default async function flow(
  input: { root: string; maxModules: number },
  tools: Tools
) {
  const [sizedListing, tree, allowedDirectories] = await Promise.all([
    tools.fs.listDirectoryWithSizes({ path: input.root }),
    tools.fs.directoryTree({ path: input.root }),
    tools.fs.listAllowedDirectories({}),
  ]);

  const searchResult = await tools.fs.searchFiles({ path: input.root, pattern: "*.ts" });
  const modulePaths = parseModulePaths(searchResult.content);

  const grades: GradedModule[] = [];
  const failures: string[] = [];
  let processed = 0;

  for (const modulePath of modulePaths) {
    if (processed >= input.maxModules) {
      break;
    }
    processed += 1;
    try {
      const info = await tools.fs.getFileInfo({ path: modulePath });
      const source = await tools.fs.readTextFile({ path: modulePath });
      const sizeBytes = parseSizeBytes(info.content);
      const grade = gradeModule(sizeBytes, source.content);
      recordGrade(grades, modulePath, grade);
    } catch (error) {
      recordFailure(failures, modulePath, error);
    }
  }

  const counts = countByGrade(grades);

  const thoughtOne = await tools.reasoning.sequentialThinking({
    thought: `Inventory: gathered the sized listing, the recursive tree and the allow-list for ${input.root}; found ${modulePaths.length} TypeScript modules and graded ${grades.length} of them within the limit of ${input.maxModules}.`,
    thoughtNumber: 1,
    totalThoughts: 3,
    nextThoughtNeeded: true,
  });
  const thoughtTwo = await tools.reasoning.sequentialThinking({
    thought: `Grading: ${counts.large} large (over 200 bytes), ${counts.documented} documented (contain /**), ${counts.plain} plain; ${failures.length} module(s) could not be read and were skipped.`,
    thoughtNumber: 2,
    totalThoughts: 3,
    nextThoughtNeeded: true,
  });
  const thoughtThree = await tools.reasoning.sequentialThinking({
    thought: `Conclusion: the audit covers ${grades.length} modules with ${failures.length} unreadable; writing audit.md with the per-module grades and this reasoning record.`,
    thoughtNumber: 3,
    totalThoughts: 3,
    nextThoughtNeeded: false,
  });
  const thoughts = [thoughtOne, thoughtTwo, thoughtThree];

  const report = buildAuditReport(
    input.root,
    grades,
    failures,
    sizedListing.content,
    tree.content,
    allowedDirectories.content
  );
  await tools.fs.writeFile({ path: `${input.root}/audit.md`, content: report });

  return {
    counts,
    thoughtsRecorded: thoughts.length,
    failures,
  };
}

import type { Tools } from "../generated/tools";

type Grade = "large" | "documented" | "plain";

interface ModuleGrade {
  path: string;
  grade: Grade;
}

interface SkippedModule {
  path: string;
  reason: string;
}

function parseModulePaths(listing: string): string[] {
  return listing
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line.length > 0);
}

function takeFirst(paths: string[], limit: number): string[] {
  return paths.slice(0, Math.max(0, limit));
}

function countLines(text: string): number {
  return text.split("\n").filter((line) => line.trim().length > 0).length;
}

function moduleSizeBytes(metadata: string, text: string): number {
  const labeled = metadata.match(/size:\s*(\d+)/i);
  if (labeled) {
    return Number(labeled[1]);
  }
  const bytes = metadata.match(/(\d+)\s*bytes/i);
  if (bytes) {
    return Number(bytes[1]);
  }
  return text.length;
}

function gradeModule(sizeBytes: number, text: string): Grade {
  if (sizeBytes > 200) {
    return "large";
  }
  if (text.includes("/**")) {
    return "documented";
  }
  return "plain";
}

function recordGrade(grades: ModuleGrade[], path: string, grade: Grade) {
  grades.push({ path, grade });
}

function recordSkipped(skipped: SkippedModule[], path: string, error: unknown) {
  skipped.push({ path, reason: String(error) });
}

function countGrades(grades: ModuleGrade[]): Record<Grade, number> {
  const counts: Record<Grade, number> = { large: 0, documented: 0, plain: 0 };
  for (const entry of grades) {
    counts[entry.grade] += 1;
  }
  return counts;
}

function summarizeGrades(grades: ModuleGrade[]): string {
  const counts = countGrades(grades);
  return `${counts.large} large, ${counts.documented} documented, ${counts.plain} plain`;
}

function renderAuditReport(
  root: string,
  tree: string,
  grades: ModuleGrade[],
  skipped: SkippedModule[],
  thoughtCount: number
): string {
  const lines: string[] = [];
  lines.push("# Repository audit");
  lines.push("");
  lines.push(`Root: ${root}`);
  lines.push("");
  lines.push("## modules");
  lines.push("");
  for (const entry of grades) {
    lines.push(`- ${entry.path}: ${entry.grade}`);
  }
  if (skipped.length > 0) {
    lines.push("");
    lines.push("## skipped");
    lines.push("");
    for (const entry of skipped) {
      lines.push(`- ${entry.path}: ${entry.reason}`);
    }
  }
  lines.push("");
  lines.push("## layout");
  lines.push("");
  lines.push(tree.trim());
  lines.push("");
  lines.push("## reasoning");
  lines.push("");
  lines.push(
    `Sequential thinking: took ${thoughtCount} thoughts (numbered 1 to ${thoughtCount} out of 3); the final thought set nextThoughtNeeded to false.`
  );
  return lines.join("\n");
}

export default async function flow(
  input: { root: string; maxModules: number },
  tools: Tools
) {
  const [sizedListing, tree, allowedDirs] = await Promise.all([
    tools.fs.listDirectoryWithSizes({ path: input.root }),
    tools.fs.directoryTree({ path: input.root }),
    tools.fs.listAllowedDirectories({}),
  ]);

  const moduleMatches = await tools.fs.searchFiles({ path: input.root, pattern: "*.ts" });
  const modules = parseModulePaths(moduleMatches.content);
  const selectedModules = takeFirst(modules, input.maxModules);

  const grades: ModuleGrade[] = [];
  const skipped: SkippedModule[] = [];

  for (const modulePath of selectedModules) {
    try {
      const info = await tools.fs.getFileInfo({ path: modulePath });
      const source = await tools.fs.readTextFile({ path: modulePath });
      const sizeBytes = moduleSizeBytes(info.content, source.content);
      const grade = gradeModule(sizeBytes, source.content);
      recordGrade(grades, modulePath, grade);
    } catch (error) {
      recordSkipped(skipped, modulePath, error);
      continue;
    }
  }

  const listingEntries = countLines(sizedListing.content);
  const gradeSummary = summarizeGrades(grades);

  const thought1 = await tools.reasoning.sequentialThinking({
    thought: `Release-checklist audit of ${input.root}. Gathered in one parallel batch: the sized directory listing (${listingEntries} entries), the recursive tree, and the allowed directories (${allowedDirs.content}). The *.ts search matched ${modules.length} modules; auditing the first ${selectedModules.length} within the cap of ${input.maxModules}.`,
    nextThoughtNeeded: true,
    thoughtNumber: 1,
    totalThoughts: 3,
  });

  const thought2 = await tools.reasoning.sequentialThinking({
    thought: `Grades are in for ${grades.length} modules: ${gradeSummary}. ${skipped.length} module(s) could not be read and were recorded as skipped instead of aborting the audit.`,
    nextThoughtNeeded: true,
    thoughtNumber: 2,
    totalThoughts: 3,
  });

  const thought3 = await tools.reasoning.sequentialThinking({
    thought: `Verdict: ${gradeSummary} across the audited module surface, with ${skipped.length} skipped. Writing audit.md with every module grade and this three-thought reasoning trace completes the checklist; no further thought needed.`,
    nextThoughtNeeded: false,
    thoughtNumber: 3,
    totalThoughts: 3,
  });

  const thoughts = [thought1, thought2, thought3];

  const report = renderAuditReport(input.root, tree.content, grades, skipped, thoughts.length);
  await tools.fs.writeFile({ path: `${input.root}/audit.md`, content: report });

  const counts = countGrades(grades);
  return {
    large: counts.large,
    documented: counts.documented,
    plain: counts.plain,
    skipped: skipped.length,
    thoughtsRecorded: thoughts.length,
  };
}
